from collections import deque, Counter

def comps(grid, target_pred, c0,c1):
    R,C=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(R):
      for c in range(c0,c1):
        if not target_pred(grid[r][c]) or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          p=q.pop(); cells.append(p)
          for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=p[0]+dr,p[1]+dc
            if 0<=nr<R and c0<=nc<c1 and (nr,nc) not in seen and target_pred(grid[nr][nc]):
              seen.add((nr,nc));q.append((nr,nc))
        comps.append(cells)
    return comps

